<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';if(!is_installed())redirect('setup.php');$token=preg_replace('/[^a-f0-9]/','',$_GET['token']??$_POST['token']??'');$st=db()->prepare("SELECT a.id,a.starts_at,a.status,p.preferred_name,p.name,u.name professional_name,t.name tenant_name FROM appointments a JOIN patients p ON p.id=a.patient_id AND p.tenant_id=a.tenant_id JOIN users u ON u.id=a.professional_id AND u.tenant_id=a.tenant_id JOIN tenants t ON t.id=a.tenant_id WHERE a.public_token=:token LIMIT 1");$st->execute(['token'=>$token]);$a=$st->fetch();$msg='';if($a&&$_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if(in_array($action,['confirmed','cancelled'],true)){db()->prepare("UPDATE appointments SET status=:s,updated_at=NOW() WHERE id=:id AND public_token=:token")->execute(['s'=>$action,'id'=>$a['id'],'token'=>$token]);$a['status']=$action;$msg=$action==='confirmed'?'Consulta confirmada. Obrigado!':'Cancelamento registrado. Entre em contato com a clínica para remarcar.';}}
layout('Confirmar atendimento',function()use($a,$token,$msg){?><div class="auth-form-wrap" style="min-height:100vh"><div class="auth-form card"><a class="brand" href="<?=e(url())?>"><span class="brand-mark">P</span><span>PsicoManager <b>AI</b></span></a><?php if(!$a):?><h1>Link inválido</h1><p>Este link não corresponde a um atendimento.</p><?php else:?><h1>Seu atendimento</h1><p><strong><?=e($a['tenant_name'])?></strong><br><?=e(date('d/m/Y \à\s H:i',strtotime($a['starts_at'])))?> · <?=e($a['professional_name'])?></p><?php if($msg):?><div class="flash success" style="margin:14px 0"><?=e($msg)?></div><?php endif?><p>Status atual: <span class="status <?=e($a['status'])?>"><?=e($a['status'])?></span></p><?php if(in_array($a['status'],['pending','confirmed'],true)):?><form method="post" class="split-actions"><?=csrf_field()?><input type="hidden" name="token" value="<?=e($token)?>"><button class="button" name="action" value="confirmed">Confirmar</button><button class="button secondary" name="action" value="cancelled">Cancelar</button></form><?php endif?><?php endif?></div></div><?php },['public'=>true]);
